INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `related_type`, `route_id`, `cms_page_id`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'How do I book a cab with Yaazh Cabs?', 'Fill the booking form on this page or call 93600 55761. We confirm your cab, driver name and number on WhatsApp within minutes.', NULL, 'general', NULL, NULL, 1, 1, '2026-08-10 12:35:12', '2026-08-10 12:35:12'),
(2, 'Do you charge for the return trip on one-way rides?', 'No. One-way trips are billed only for the distance you travel, plus driver bata and applicable tolls or permits.', NULL, 'general', NULL, NULL, 2, 1, '2026-08-10 12:35:12', '2026-08-10 12:35:12'),
(3, 'Are night-time and early morning pickups available?', 'Yes. We operate 24×7, including airport pickups at 2 AM. Book at least 3 hours ahead for night trips wherever possible.', NULL, 'general', NULL, NULL, 3, 1, '2026-08-10 12:35:12', '2026-08-10 12:35:12'),
(4, 'Which vehicles can I choose from?', 'Dzire sedans, Ertiga and Innova MPVs, full-size SUVs and 14-seat tempo travellers for groups and tour packages.', NULL, 'general', NULL, NULL, 4, 1, '2026-08-10 12:35:12', '2026-08-10 12:35:12'),
(5, 'How is the final fare calculated?', 'Base fare plus per-kilometre rate for your chosen vehicle. Tolls, parking, state permits and driver allowance are billed at actuals and shown up front.', NULL, 'general', NULL, NULL, 5, 1, '2026-08-10 12:35:12', '2026-08-10 12:35:12'),
(6, 'Do you cover Ooty, Kodaikanal and Kerala?', 'Absolutely. Outstation and tour packages to Ooty, Kodaikanal, Valparai, Munnar and across Kerala are among our most-booked trips.', NULL, 'general', NULL, NULL, 6, 1, '2026-08-10 12:35:12', '2026-08-10 12:35:12');

